const { chromium } = require('playwright');
const axe = require('axe-core');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.setContent(fs.readFileSync('index.html', 'utf8'), { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });

  const summarize = (violations) => violations.map((v) => ({
    id: v.id,
    impact: v.impact,
    tags: v.tags,
    targets: v.nodes.map((n) => n.target)
  }));

  const collapsed = await page.evaluate(async () => await window.axe.run());
  await page.locator('.question').evaluateAll((buttons) => buttons.forEach((button) => button.click()));
  const expanded = await page.evaluate(async () => await window.axe.run());
  await browser.close();

  const all = [...collapsed.violations, ...expanded.violations];
  const wcag = all.filter((v) => !v.tags.includes('best-practice'));
  const bestPractice = all.filter((v) => v.tags.includes('best-practice'));
  console.log(JSON.stringify({ collapsed: summarize(collapsed.violations), expanded: summarize(expanded.violations), wcag: summarize(wcag), bestPractice: summarize(bestPractice) }, null, 2));
  process.exit(wcag.length ? 1 : 0);
})().catch((error) => {
  console.error(error.message);
  process.exit(2);
});
